# Wire a button so it opens a door through a logic_relay.
# In the editor: button.pressed -> relay.trigger, relay.relayed -> door.open.
extends Node

func _ready() -> void:
	var relay := get_node("logic_relay_gate")
	var door := get_node("func_door_gate")

	# Fire the relay from code, the same as the editor I/O would.
	relay.connect("relayed", Callable(door, "open"))
	relay.call("trigger", self)   # activator is passed through
